script:
frappe.ui.form.on('Project', {
	field: function(frm) {
		// When field is selected, auto-populate farm
		if (frm.doc.field && !frm.doc.farm) {
			frappe.db.get_value('Field', frm.doc.field, 'farm', (r) => {
				if (r && r.farm) {
					frm.set_value('farm', r.farm);
				}
			});
		}
	},

	area_under_cultivation: function(frm) {
		// Auto-calculate expected total yield
		if (frm.doc.area_under_cultivation && frm.doc.expected_yield_per_unit) {
			frm.set_value('expected_total_yield',
				frm.doc.area_under_cultivation * frm.doc.expected_yield_per_unit);
		}
	},

	expected_yield_per_unit: function(frm) {
		// Auto-calculate expected total yield
		if (frm.doc.area_under_cultivation && frm.doc.expected_yield_per_unit) {
			frm.set_value('expected_total_yield',
				frm.doc.area_under_cultivation * frm.doc.expected_yield_per_unit);
		}
	}
});
